import { Worker } from 'node:worker_threads'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

// The worker file name is only known at runtime, so the bundler has to consider
// every file in this directory, including the declaration files next to it.
export function startWorker(name = 'worker.cjs') {
  return new Worker(join(dirname(fileURLToPath(import.meta.url)), name))
}
